def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return [row[:] for row in grid]

    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    ph, pw = r1 - r0 + 1, c1 - c0 + 1

    # Reconstruct each hidden row from another row containing the same
    # sequence immediately to the right of the hidden rectangle.
    result = [[0] * pw for _ in range(ph)]
    for i in range(ph):
        r = r0 + i
        seq = grid[r][c1 + 1:] if c1 + 1 < w else []
        if not seq:
            continue

        best_key = None
        best_vals = None
        for sr in range(h):
            if r0 <= sr <= r1:
                continue
            for start in range(pw, w):
                if start < pw:
                    continue
                vals = grid[sr]
                if any(v == 8 for v in vals[max(0, start-pw):start]):
                    continue

                n = min(len(seq), w - start)
                if n <= 0:
                    continue
                prefix = 0
                while prefix < n and seq[prefix] == vals[start + prefix]:
                    prefix += 1
                matches = sum(seq[k] == vals[start + k] for k in range(n))
                key = (prefix, matches, n)
                if best_key is None or key > best_key:
                    best_key = key
                    best_vals = vals[start-pw:start]

        if best_vals and len(best_vals) == pw:
            result[i] = best_vals[:]

    # Rows with identical visible portions represent the same hidden row.
    for i in range(ph):
        for j in range(i):
            ra, rb = r0 + i, r0 + j
            if grid[ra][c1+1:] == grid[rb][c1+1:]:
                result[i] = result[j][:]
                break

    return result
